import{_ as a,g as t,e as r,a4 as o}from"./chunks/framework.CEYJDsBW.js";const p=JSON.parse('{"title":"手持顺序、护符盒与内置图腾","description":"","frontmatter":{},"headers":[],"relativePath":"anvilcraft/21.1/totems/box.md","filePath":"anvilcraft/21.1/totems/box.md"}'),i={name:"anvilcraft/21.1/totems/box.md"};function d(n,e,s,c,l,b){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="手持顺序、护符盒与内置图腾" tabindex="-1">手持顺序、护符盒与内置图腾 <a class="header-anchor" href="#手持顺序、护符盒与内置图腾" aria-label="Permalink to &quot;手持顺序、护符盒与内置图腾&quot;">​</a></h1><p>让余烬符也能装进护符盒，需要为 <code>workshop:ember_ward</code> 增加物品标签。把下列文件写到 <code>data/anvilcraft/tags/item/totem.json</code>，服务器重载数据后盒子便能识别已注册的余烬符。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;replace&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;values&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workshop:ember_ward&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}</span></span></code></pre></div><p>死亡保护先检查主手、再检查副手。玩家还会检查口袋中的护符盒，口袋中单独放一枚图腾不会进入这组候选。对匹配物品先调用外层 <code>canExecute</code>，再调用 <code>CommonHooks.onLivingUseTotem</code>。口袋盒也按副手向该钩子报告。第一个通过两道判断的物品独占此次尝试。</p><p>盒子的 <code>canExecute</code> 只检查图腾列表非空。<code>execute</code> 取列表第一项，根据物品查处理器，直接调用它的 <code>execute</code>。成功后，盒子的 <code>shrink</code> 将 <code>BoxContents</code> 转成可变副本，移除第一项，再写回 <code>BOX_CONTENTS</code>。即使第二枚图腾能生效，第一枚失败时也不会跳到它。滚轮选中的是玩家要取出的物品，死亡保护始终取队首。<a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/totem/handler/AmuletBoxHandler.java" target="_blank" rel="noreferrer">护符盒处理器</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/item/property/component/BoxContents.java" target="_blank" rel="noreferrer">容量与取出</a></p><table tabindex="0"><thead><tr><th>内置处理器</th><th>何时成功</th><th>处理结果</th></tr></thead><tbody><tr><td><code>TotemOfUndyingHandler</code></td><td>伤害不属于 <code>BYPASSES_INVULNERABILITY</code>。</td><td>生命设为 1，清除可被图腾治疗的效果，添加再生、伤害吸收、抗火，播放实体事件 35。</td></tr><tr><td><code>TotemOfRecoveryHandler</code></td><td>伤害不是 <code>GENERIC_KILL</code>。</td><td>恢复与不死图腾相同的基本状态。服务端玩家额外获得回溯珍珠、记录死亡位置并传往重生点。</td></tr><tr><td><code>TotemOfRageHandler</code></td><td>伤害不属于 <code>BYPASSES_INVULNERABILITY</code>。</td><td>生命回满，清效果后添加狂怒等效果；成功触发的实体在后续 <code>baseTick</code> 接受持续时间检查。生存或冒险玩家会在期限后死亡。</td></tr></tbody></table><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/totem/handler/TotemOfUndyingHandler.java" target="_blank" rel="noreferrer">不死</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/totem/handler/TotemOfRecoveryHandler.java" target="_blank" rel="noreferrer">恢复</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/api/totem/handler/TotemOfRageHandler.java" target="_blank" rel="noreferrer">狂怒</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/mixin/LivingEntityMixin.java" target="_blank" rel="noreferrer">狂怒计时与候选顺序</a></p>',7)])])}const v=a(i,[["render",d]]);export{p as __pageData,v as default};
